def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    highest_prev = 0.0
    cindy_prev = None
    urgent_opp_count = 0
    rich_opp_count = 0

    for oid, opp in alive:
        if float(opp.get('budget', 0.0)) >= DAILY_SALARY * 4:
            rich_opp_count += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 2:
            urgent_opp_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            if bid > highest_prev:
                highest_prev = bid
            if oid == 'Cindy':
                cindy_prev = bid

    slots = int(supply // WATER_REQ)
    scarce = slots <= 1
    abundant = slots >= 2

    if cindy_prev is None:
        cindy_prev = highest_prev if highest_prev > 0 else DAILY_SALARY * 0.8

    danger = hp <= 2 or no_water >= 2
    caution = hp <= 4 or no_water >= 1

    if danger:
        target = max(DAILY_SALARY * 1.15, cindy_prev + 3.0)
    elif scarce:
        if cindy_prev >= 110:
            target = DAILY_SALARY * 0.42 if hp > 4 and no_water == 0 else DAILY_SALARY * 1.05
        else:
            target = max(DAILY_SALARY * 0.9, cindy_prev + 2.0)
    elif abundant:
        target = DAILY_SALARY * 0.28
        if caution and rich_opp_count >= 1:
            target = DAILY_SALARY * 0.52
        if urgent_opp_count >= 2:
            target = max(target, DAILY_SALARY * 0.6)
    else:
        target = DAILY_SALARY * 0.5

    if day >= 8:
        if hp > 4 and no_water == 0 and abundant:
            target = min(target, DAILY_SALARY * 0.22)
        elif caution:
            target = max(target, DAILY_SALARY * 0.82)

    if budget < DAILY_SALARY * 2 and not danger:
        target = min(target, DAILY_SALARY * 0.55)

    bid = max(0.0, min(budget, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents alive, bid conservatively.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: if supply is low, competition for water is higher.
    # Normalize to [0,1] where 0=MIN_SUPPLY, 1=MAX_SUPPLY.
    if MAX_SUPPLY - MIN_SUPPLY > 0:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base aggressiveness: Cindy survived with high average bids; match only when needed.
    # If we are low hp or have had no water days, we must secure water.
    must_have = (hp <= 3.0) or (no_water_days >= 2)

    # Estimate how much to bid.
    # - If someone previously bid very high, raise our bid to avoid losing.
    # - Otherwise, bid around a fraction of salary.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure environment.
        if must_have:
            target = DAILY_SALARY * 0.95
        else:
            target = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.55)
    else:
        # Moderate pressure environment.
        # If supply is low, increase slightly.
        supply_factor = 1.0 + (1.0 - supply_norm) * 0.35
        if must_have:
            target = DAILY_SALARY * 0.75 * supply_factor
        else:
            target = DAILY_SALARY * 0.45 * supply_factor

    # Late-episode slight escalation to avoid running out.
    if day >= 7:
        target *= 1.08

    # Ensure we never exceed budget.
    bid = max(0.0, min(budget, target))
    return bid

